use Modules\Rental\Importer;
final class Workbook {
    private const NS='http://schemas.openxmlformats.org/spreadsheetml/2006/main';
    private const FIELDS=['C'=>'tenant','D'=>'service','E'=>'contract','H'=>'floor','I'=>'designation','J'=>'area','AA'=>'cadastral','AB'=>'account'];
    public static function normalized(string $v):string{return preg_replace('/\s+/u',' ',trim(mb_convert_case($v,MB_CASE_FOLD,'UTF-8')));}
    public static function identity(string $address,string $floor,string $designation,string $cad):string {return hash('sha256','['.implode(', ',array_map(fn($v)=>json_encode(self::normalized($v),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),[$address,$floor,$designation,$cad])).']');}
    private static function xml(string $raw):\DOMDocument {if(stripos($raw,'<!DOCTYPE')!==false||stripos($raw,'<!ENTITY')!==false)throw new \RuntimeException('XML entities не разрешены');$dom=new \DOMDocument();if(!$dom->loadXML($raw,LIBXML_NONET|LIBXML_COMPACT))throw new \RuntimeException('Повреждён XML книги');return $dom;}
    private static function xpath(\DOMDocument $dom):\DOMXPath {$x=new \DOMXPath($dom);$x->registerNamespace('s',self::NS);return $x;}
    private static function number(string $raw):string {if($raw==='')return '';try{$n=Importer::decodeExact('['.$raw.']')[0];if(!is_string($n)&&!is_int($n))throw new \RuntimeException('Number type');return (string)$n;}catch(\Throwable){throw new \RuntimeException('Недопустимое число в XML');}}
    private static function textNumber(string $raw,string $format):string {if($raw==='')return '';$mask=explode(';',$format)[0];$v=self::number($raw);if(preg_match('/^0+$/D',$mask))return str_pad(bcadd($v,'0',0),strlen($mask),'0',STR_PAD_LEFT);if(preg_match('/^0+\.(0+)$/D',$mask,$m))return bcround($v,strlen($m[1]),\RoundingMode::HalfEven);return $raw;}
    public static function read(string $path):array {
        if(!is_file($path)||is_link($path)||filesize($path)>50000000)throw new \RuntimeException('Недопустимая книга');$z=new \ZipArchive();if($z->open($path)!==true)throw new \RuntimeException('Не удалось прочитать XLSX');$sum=0;if($z->numFiles>5000)throw new \RuntimeException('Слишком много файлов в книге');for($i=0;$i<$z->numFiles;$i++){$entry=$z->statIndex($i);$sum+=$entry['size'];if($entry['size']>20000000||$sum>100000000)throw new \RuntimeException('Книга превышает лимит распаковки');}
