            $styles=self::xpath(self::xml($get('xl/styles.xml')));$formats=['0'=>'General','1'=>'0','2'=>'0.00','49'=>'@'];foreach($styles->query('/s:styleSheet/s:numFmts/s:numFmt')as $f)$formats[$f->getAttribute('numFmtId')]=$f->getAttribute('formatCode');$xfs=[];foreach($styles->query('/s:styleSheet/s:cellXfs/s:xf')as $f)$xfs[]=$formats[$f->getAttribute('numFmtId')]??'General';
            $xs=self::xpath(self::xml($get($sheetPath)));$rows=[];$title='';foreach($xs->query('/s:worksheet/s:sheetData/s:row')as $row){$cells=[];foreach($xs->query('./s:c',$row)as $c){$column=preg_replace('/\d/','',$c->getAttribute('r'));$v=$xs->query('./s:v',$c)->item(0)?->textContent??'';$type=$c->getAttribute('t')?:'n';$format=$xfs[(int)($c->getAttribute('s')?:0)]??'General';$value=$v;if($type==='s'){$value=$shared[(int)$v]??throw new \RuntimeException('Некорректный sharedString');}elseif($type==='inlineStr'){$value='';foreach($xs->query('.//s:t',$c)as $t)$value.=$t->textContent;}elseif($type==='n')$value=self::textNumber($v,$format);$cells[$column]=['value'=>$value,'type'=>$type,'format'=>$format,'formula'=>$xs->query('./s:f',$c)->item(0)?->textContent??''];}
                $number=(int)$row->getAttribute('r');if($number===1)$title=$cells['B']['value']??'';if($number<4||trim($cells['C']['value']??'')===''||trim($cells['D']['value']??'')==='')continue;$record=['row'=>$number,'hidden'=>$row->getAttribute('hidden')==='1','cells'=>[]];foreach(self::FIELDS as $column=>$name){$record['cells'][$column]=$cells[$column]??['value'=>''];$record[$name]=trim($cells[$column]['value']??'');}$rows[]=$record;
