        }finally{$z->close();}
    }
    public static function area(string $v):?string {try{$value=self::number(str_replace(',','.',$v));if(!preg_match('/^\d+(?:\.\d+)?$/D',$value)||bccomp($value,'0',20)<=0)return null;$int=ltrim(explode('.',$value)[0],'0');if($int!=='')$precision=15-strlen($int);else{preg_match('/^0?\.(0*)/',$value,$m);$precision=15+strlen($m[1]??'');}$value=bcround($value,$precision,\RoundingMode::HalfEven);if(bccomp($value,bcround($value,3,\RoundingMode::HalfEven),20)!==0)return null;$value=bcadd($value,'0',3);return str_contains($value,'.')?rtrim(rtrim($value,'0'),'.'):$value;}catch(\Throwable){return null;}}
    public static function prepare(array $input):array {
        $address=$input['address'];$rows=$input['rows'];$groups=[];$issues=[];$pending=[];$lists=[];$unresolved=0;
        $reject=static function(int $index,string $reason)use(&$rows,&$issues,&$unresolved):void{$rows[$index]['reason']=$reason;$issues[]=['rows'=>[$rows[$index]['row']],'reason'=>$reason];$unresolved++;};
        foreach($rows as $i=>&$row){$formula=false;foreach(['H','I','J','AA','AB']as $col)if(!empty($row['cells'][$col]['formula']))$formula=true;if($formula){$reject($i,'Идентифицирующее поле задано формулой: требуется проверка.');continue;}if(!$row['designation']||!$row['floor']){$reject($i,'Нет обозначения помещения или этажа; кадастровый номер не определяет сдаваемую часть.');continue;}$list=false;foreach(['designation','floor','cadastral','account']as $field)if(preg_match('/[,;\n]/u',$row[$field]))$list=true;if($list){$lists[]=$i;continue;}if(preg_match('/Н\/(\d+)$/ui',$row['designation'],$m)&&$m[1]!==$row['floor']){$reject($i,'Этаж не совпадает с этажом в обозначении помещения.');continue;}$area=self::area($row['area']);if($area===null){$reject($i,'Нет корректной положительной площади.');continue;}$row['area']=$area;if($row['cadastral']===''){$pending[]=$i;continue;}if(!preg_match('/^\d+:\d+:\d+:\d+$/D',$row['cadastral'])){$reject($i,'Кадастровая связь требует проверки.');continue;}$key=self::identity($address,$row['floor'],$row['designation'],$row['cadastral']);$groups[$key]??=['key'=>$key,'address'=>$address,'floor'=>$row['floor'],'designation'=>$row['designation'],'cadastral_number'=>$row['cadastral'],'indexes'=>[]];$groups[$key]['indexes'][]=$i;$row['keys']=[$key];}unset($row);
        foreach($pending as $i){$r=$rows[$i];$candidates=[];foreach($groups as $key=>$g){$areas=array_map(fn($j)=>$rows[$j]['area'],$g['indexes']);$accounts=array_map(fn($j)=>$rows[$j]['account'],$g['indexes']);if(self::normalized($g['designation'])===self::normalized($r['designation'])&&self::normalized($g['floor'])===self::normalized($r['floor'])&&in_array($r['area'],$areas,true)&&($r['account']===''||in_array($r['account'],$accounts,true)))$candidates[]=$key;}if(count($candidates)!==1)$reject($i,'Нет единственного помещения с теми же этажом, обозначением, площадью и совместимым лицевым счётом.');else{$key=$candidates[0];$groups[$key]['indexes'][]=$i;$rows[$i]['keys']=[$key];}}
        $grouped=0;$split=static fn($v)=>array_values(array_filter(array_map('trim',preg_split('/[,;\n]/u',$v)),fn($s)=>$s!==''));
        foreach($lists as $i){$r=$rows[$i];$names=$split($r['designation']);$floors=$split($r['floor']);$cads=$split($r['cadastral']);$accounts=$split($r['account']);$choices=[];$assignments=[];$n=count($names);if($n>1&&$n<=8&&in_array(count($floors),[1,$n],true)&&in_array(count($cads),[0,$n],true)&&in_array(count($accounts),[0,$n],true)){
                foreach($names as $j=>$name){$floor=count($floors)===1?$floors[0]:$floors[$j];$choice=[];foreach($groups as $key=>$g){$gas=array_values(array_unique(array_filter(array_map(fn($k)=>$rows[$k]['account'],$g['indexes']),fn($v)=>$v!=='')));$areas=array_unique(array_map(fn($k)=>$rows[$k]['area'],$g['indexes']));if(self::normalized($g['designation'])===self::normalized($name)&&self::normalized($g['floor'])===self::normalized($floor)&&(!$cads||$g['cadastral_number']===$cads[$j])&&(!$accounts||$gas===[$accounts[$j]])&&count($areas)===1)$choice[]=$key;}$choices[]=$choice;}$size=1;foreach($choices as $choice)$size*=count($choice);$total=self::area($r['area']);if($size>0&&$size<=10000&&$total!==null){$walk=function(int $pos,array $keys,string $sum)use(&$walk,&$assignments,$choices,$groups,$rows,$total):void {if(count($assignments)>1)return;if($pos===count($choices)){if(bccomp($sum,$total,3)===0)$assignments[]=$keys;return;}foreach($choices[$pos]as $key)if(!in_array($key,$keys,true))$walk($pos+1,array_merge($keys,[$key]),bcadd($sum,$rows[$groups[$key]['indexes'][0]]['area'],3));};$walk(0,[],'0');}}
            if(count($assignments)===1){$rows[$i]['keys']=$assignments[0];$grouped++;}else $reject($i,'Несколько объектов/реквизитов: нет единственного соответствия обозначений, этажей, индивидуальных площадей и реквизитов. Список не разделён.');}
        foreach($groups as $key=>&$g){$g['rows']=array_map(fn($i)=>$rows[$i],$g['indexes']);$g['area_variants']=array_values(array_unique(array_column($g['rows'],'area')));usort($g['area_variants'],fn($a,$b)=>bccomp($a,$b,3));$g['account_variants']=array_values(array_unique(array_filter(array_column($g['rows'],'account'),fn($v)=>$v!=='')));sort($g['account_variants']);$g['area']=count($g['area_variants'])===1?$g['area_variants'][0]:null;$g['account']=count($g['account_variants'])===1?$g['account_variants'][0]:'';$kinds=[];foreach($g['rows']as $r){$service=mb_strtolower($r['service']);if(str_contains($service,'аренда')||str_contains($service,'паркинг'))$kinds[]=str_contains($service,'паркинг')?'parking':(str_contains(mb_strtolower($r['designation']),'часть')?'part':'room');}$kinds=array_values(array_unique($kinds?:[str_contains(mb_strtolower($g['designation']),'часть')?'part':'room']));$g['kind']=count($kinds)===1?$kinds[0]:'room';$g['parent_description']='Здание: '.$address.'; кадастровый объект: '.$g['cadastral_number'];$g['note']='Площадь относится к арендуемой единице из реестра; полная площадь кадастрового объекта не установлена.';$reasons=[];if(count($g['area_variants'])>1)$reasons[]='Разные площади: '.implode(', ',$g['area_variants']).' м². Площадь карточки не выбрана.';if(count($g['account_variants'])>1)$reasons[]='Разные лицевые счета: '.implode(', ',$g['account_variants']).'. Счёт карточки не выбран.';if(count($kinds)>1)$reasons[]='Разные виды по услугам: требуется проверка.';if($reasons){$reason=implode(' ',$reasons);$g['note'].=' '.$reason;$issues[]=['rows'=>array_column($g['rows'],'row'),'reason'=>$reason,'key'=>$key];}unset($g['indexes']);}unset($g);
        $byName=[];$byCad=[];$byAccount=[];foreach($groups as $key=>$g){$byName[$g['floor'].'|'.self::normalized($g['designation'])][]=$key;$byCad[$g['cadastral_number']][]=$key;foreach($g['account_variants']as $account)$byAccount[$account][]=$key;}
        foreach($byName as $keys)if(count($keys)>1)$issues[]=['keys'=>$keys,'reason'=>'Одинаковые этаж и обозначение при разных кадастровых объектах. Сохранены отдельные карточки с точными реквизитами; проверить идентичность.'];foreach($byCad as $cad=>$keys){if(count($keys)<2)continue;$floors=array_unique(array_map(fn($k)=>$groups[$k]['floor'],$keys));$overlap=false;foreach($keys as $i=>$a)foreach(array_slice($keys,$i+1)as $b)if(array_intersect($groups[$a]['area_variants'],$groups[$b]['area_variants']))$overlap=true;if(count($floors)>1||$overlap)$issues[]=['keys'=>$keys,'reason'=>'Кадастровый объект '.$cad.' связан с разными обозначениями при совпадающих площадях или разных этажах. Возможны части или альтернативные обозначения; автоматически не объединены.'];}foreach($byAccount as $account=>$keys)if(count(array_unique(array_map(fn($k)=>$groups[$k]['cadastral_number'],$keys)))>1)$issues[]=['keys'=>$keys,'reason'=>'Лицевой счёт '.$account.' встречается у разных кадастровых объектов. Не использован для объединения.'];
        foreach($issues as &$issue){$keys=$issue['keys']??(isset($issue['key'])?[$issue['key']]:[]);if(!isset($issue['rows'])){$issue['rows']=[];foreach($keys as $key)$issue['rows']=array_merge($issue['rows'],array_column($groups[$key]['rows'],'row'));sort($issue['rows']);}foreach($keys as $key)if(!str_contains($groups[$key]['note'],$issue['reason']))$groups[$key]['note'].=' '.$issue['reason'];}unset($issue);
        return ['address'=>$address,'rows'=>$rows,'groups'=>array_values($groups),'issues'=>$issues,'summary'=>['source_rows'=>count($rows),'hidden_rows'=>count(array_filter($rows,fn($r)=>$r['hidden'])),'premises'=>count($groups),'linked_rows'=>count(array_filter($rows,fn($r)=>!empty($r['keys']))),'merged_repetitions'=>array_sum(array_map(fn($g)=>count($g['rows'])-1,$groups)),'grouped_rows_linked'=>$grouped,'source_links'=>array_sum(array_map(fn($r)=>count($r['keys']??[]),$rows)),'unresolved_rows'=>$unresolved,'issue_groups'=>count($issues)]];
    }
